#!/usr/bin/env node
/*
 * Binding generator.
 *
 *   node api/generate.mjs           write the generated files
 *   node api/generate.mjs --check   fail if a generated file is stale or the spec
 *                                   and js/bridge.ts disagree on the method list
 *
 * Two sources, everything else is derived:
 *  - api/api.json: the library methods (JS bridge methods reached through
 *    niim_call_bin) and their types -> typed methods and records for Go, Rust,
 *    Python, Swift and Kotlin, and the method list in include/niimblue.h.
 *  - include/niimblue.h: the C functions -> the FFI declarations of the bindings
 *    that can't import a C header (Rust `sys`, Python ctypes). Go (cgo) and
 *    Swift (clang module) import the header directly.
 *
 * What stays hand-written per binding is the core that C can't describe:
 * handle lifetime, callbacks (events, custom transport), error mapping and
 * native image helpers. Output is deterministic (Go files go through gofmt).
 */

import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const CHECK = process.argv.includes("--check");
const HEADER = "Code generated by api/generate.mjs from api/api.json. DO NOT EDIT.";
const FFI_HEADER = "Code generated by api/generate.mjs from include/niimblue.h. DO NOT EDIT.";
const LANGS = ["go", "rust", "python", "swift", "kotlin"];

const read = (rel) => readFileSync(join(ROOT, rel), "utf8");
const fail = (msg) => {
  console.error(`api: ${msg}`);
  process.exit(1);
};

/* ======================================================================== */
/* Spec                                                                     */
/* ======================================================================== */

const spec = JSON.parse(read("api/api.json"));
const errors = [];

const SCALARS = new Set(["int", "int64", "bool", "string", "json", "bytes"]);
const PARAM_SCALARS = new Set(["int", "bool", "string", "json", "bytes"]);
const SCALAR_RESULTS = new Set(["void", "bool", "int", "string", "json"]);

const parseType = (t) => {
  const optional = t.endsWith("?");
  const base0 = optional ? t.slice(0, -1) : t;
  const list = base0.endsWith("[]");
  return { optional, list, base: list ? base0.slice(0, -2) : base0, raw: t };
};

const types = Object.fromEntries(
  Object.entries(spec.types ?? {}).map(([name, t]) => [
    name,
    { ...t, name, fields: t.fields.map((f) => ({ ...f, t: parseType(f.type) })) },
  ]),
);
const records = Object.values(types).filter((t) => t.record);

const methods = spec.methods.map((m) => ({
  ...m,
  params: (m.params ?? []).map((p) => ({ ...p, t: parseType(p.type) })),
  r: parseType(m.result ?? "void"),
  skip: new Set(m.skip ?? []),
  consts: Object.entries(m.const ?? {}),
}));

const isRecordParam = (p) => p.t.list && types[p.t.base]?.record;
const bytesOf = (rec) => rec.fields.filter((f) => f.t.base === "bytes");

{
  const seenName = new Set();
  for (const m of methods) {
    if (seenName.has(m.name)) errors.push(`duplicate name ${m.name}`);
    seenName.add(m.name);
    for (const l of [...m.skip, ...Object.keys(m.names ?? {})]) {
      if (!LANGS.includes(l)) errors.push(`${m.name}: unknown language ${l}`);
    }
    let binary = 0;
    let seenOptional = false;
    for (const p of m.params) {
      if (isRecordParam(p)) {
        if (p.t.optional) errors.push(`${m.name}.${p.name}: record lists can't be optional`);
        if (bytesOf(types[p.t.base]).length) binary++;
      } else if (!PARAM_SCALARS.has(p.t.base) || p.t.list) {
        errors.push(`${m.name}.${p.name}: bad param type ${p.type}`);
      } else if (p.t.base === "bytes") {
        binary++;
        if (p.t.optional) errors.push(`${m.name}.${p.name}: bytes can't be optional`);
      }
      if (p.t.optional) seenOptional = true;
      else if (seenOptional) errors.push(`${m.name}: required param ${p.name} after an optional one`);
    }
    if (binary > 1) errors.push(`${m.name}: more than one binary payload`);
    const r = m.r;
    if (!(SCALAR_RESULTS.has(r.base) || r.base in types || /^[A-Z]\w*$/.test(r.base))) {
      errors.push(`${m.name}: unknown result type ${m.result}`);
    }
  }
  for (const t of Object.values(types)) {
    for (const f of t.fields) {
      if (!SCALARS.has(f.t.base) && !(f.t.base in types) && !/^[A-Z]\w*$/.test(f.t.base)) {
        errors.push(`type ${t.name}.${f.name}: unknown type ${f.type}`);
      }
    }
    if (t.record) {
      if (bytesOf(t).length > 1) errors.push(`record ${t.name}: more than one bytes field`);
      for (const f of t.fields) {
        if (!PARAM_SCALARS.has(f.t.base) || f.t.list) errors.push(`record ${t.name}.${f.name}: records hold scalars only`);
      }
    }
  }
}

/* Spec and bridge must list the same methods. */
{
  const sf = ts.createSourceFile("bridge.ts", read("js/bridge.ts"), ts.ScriptTarget.Latest, true);
  let bridgeMethods;
  const visit = (node) => {
    if (
      ts.isVariableDeclaration(node) &&
      node.name.getText(sf) === "methods" &&
      node.initializer &&
      ts.isObjectLiteralExpression(node.initializer)
    ) {
      bridgeMethods = node.initializer.properties.map((p) => p.name.getText(sf).replace(/^["']|["']$/g, ""));
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);
  if (!bridgeMethods) {
    errors.push("js/bridge.ts: `const methods = {...}` not found");
  } else {
    const known = new Set([...methods.map((m) => m.method), ...(spec.internal ?? [])]);
    for (const m of bridgeMethods) {
      if (!known.has(m)) errors.push(`js/bridge.ts method ${m} is missing in api/api.json (add it to "methods" or "internal")`);
    }
    const inBridge = new Set(bridgeMethods);
    for (const m of known) if (!inBridge.has(m)) errors.push(`api/api.json method ${m} does not exist in js/bridge.ts`);
  }
}

if (errors.length) fail(errors.join("\napi: "));

/* ======================================================================== */
/* Helpers                                                                  */
/* ======================================================================== */

const pascal = (s) => s[0].toUpperCase() + s.slice(1);
const snake = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase();
const camel = (s) => s;
const CONV = { go: pascal, rust: snake, python: snake, swift: camel, kotlin: camel };
const methodName = (m, lang) => m.names?.[lang] ?? CONV[lang](m.name);
const typeName = (t, lang) => t.names?.[lang] ?? t.name;
const forLang = (lang) => methods.filter((m) => !m.skip.has(lang));
const quote = (s) => JSON.stringify(s);
const jsonParams = (m) => m.params.filter((p) => p.t.base !== "bytes");
const bytesParam = (m) => m.params.find((p) => p.t.base === "bytes");
const recordParam = (m) => m.params.find((p) => isRecordParam(p) && bytesOf(types[p.t.base]).length);
const hasBinary = (m) => !!(bytesParam(m) || recordParam(m));
const isTyped = (r) => !SCALAR_RESULTS.has(r.base);

function wrap(text, width = 96) {
  const out = [];
  let line = "";
  for (const word of text.split(/\s+/)) {
    if (line && line.length + 1 + word.length > width) {
      out.push(line);
      line = word;
    } else {
      line = line ? `${line} ${word}` : word;
    }
  }
  if (line) out.push(line);
  return out;
}
const docLines = (prefix, text, width) => wrap(text, width).map((l) => `${prefix}${l}`);

const KEYWORDS = {
  go: new Set(["type", "func", "range", "map", "chan", "select", "default", "go", "var", "interface", "package"]),
  rust: new Set(["type", "fn", "match", "ref", "self", "move", "impl", "loop", "mod", "use", "where", "crate"]),
  python: new Set(["from", "import", "class", "def", "in", "is", "lambda", "pass", "global", "with", "yield"]),
  swift: new Set(["func", "class", "struct", "var", "let", "in", "is", "protocol", "extension", "repeat"]),
  kotlin: new Set(["fun", "val", "var", "in", "is", "object", "class", "interface", "when", "typealias"]),
};
const ident = (lang, name) => {
  const n = lang === "rust" || lang === "python" ? snake(name) : lang === "go" ? name.replace(/Id$/, "ID") : name;
  return KEYWORDS[lang].has(n) ? `${n}_` : n;
};
const fieldName = (f, lang) => f.names?.[lang] ?? (lang === "go" ? f.go ?? pascal(f.name) : ident(lang, f.name));

const constKind = (v) => (typeof v === "boolean" ? "bool" : typeof v === "number" ? "int" : "string");
const scalarKind = (base) => ({ int: "int", bool: "bool", string: "string", json: "raw" })[base];

/* ======================================================================== */
/* Go                                                                       */
/* ======================================================================== */

function goType(t, { field = false } = {}) {
  const base =
    { int: "int", int64: "int64", bool: "bool", string: "string", json: "json.RawMessage", bytes: "[]byte" }[t.base] ??
    (types[t.base] ? typeName(types[t.base], "go") : t.base);
  if (t.list) return `[]${base}`;
  if (field && t.optional && !SCALARS.has(t.base)) return `*${base}`;
  return base;
}

function goFile(body) {
  const text = body.join("\n");
  const imp = text.includes("json.") ? 'import "encoding/json"\n\n' : "";
  return gofmt(`// ${HEADER}\n\npackage niimblue\n\n${imp}${text}`);
}

function gofmt(src) {
  try {
    return execFileSync("gofmt", [], { input: src, encoding: "utf8" });
  } catch (e) {
    fail("gofmt failed (is Go installed?)\n" + (e.stderr ?? e.message) + "\n" + src);
  }
}

function goMethods() {
  const L = [];
  for (const m of forLang("go")) {
    const name = methodName(m, "go");
    const args = m.params.map((p) => `${ident("go", p.name)} ${p.go ?? goType(p.t)}`).join(", ");
    const r = m.r;
    let ret, decl, tail;
    if (r.base === "void") {
      ret = "error";
    } else if (r.list) {
      ret = `(${goType({ ...r, optional: false })}, error)`;
      decl = `var r ${goType({ ...r, optional: false })}`;
      tail = "return r, err";
    } else if (isTyped(r)) {
      const tn = goType({ ...r, optional: false });
      ret = `(*${tn}, error)`;
      decl = r.optional ? `var r *${tn}` : `r := new(${tn})`;
      tail = "if err != nil {\n\t\treturn nil, err\n\t}\n\treturn r, nil";
    } else {
      ret = `(${goType(r)}, error)`;
      decl = `var r ${goType(r)}`;
      tail = "return r, err";
    }
    L.push(...docLines("// ", `${name} calls "${m.method}": ${m.doc}`));
    L.push(`func (p *Printer) ${name}(${args}) ${ret} {`);
    let params = "nil";
    let data = "nil";
    if (jsonParams(m).length || m.consts.length) {
      L.push("\tparams := apiParams{}");
      params = "params";
    }
    for (const [k, v] of m.consts) L.push(`\tparams.set(${quote(k)}, ${JSON.stringify(v)})`);
    for (const p of jsonParams(m)) {
      const id = ident("go", p.name);
      if (isRecordParam(p)) {
        const rec = types[p.t.base];
        const bf = bytesOf(rec)[0];
        if (bf) {
          L.push("\tvar data []byte");
          data = "data";
        }
        L.push(`\tlist := make([]apiParams, len(${id}))`, `\tfor i, it := range ${id} {`, "\t\tr := apiParams{}");
        for (const f of rec.fields) {
          const fn = fieldName(f, "go");
          if (f === bf) {
            L.push(`\t\tr.set("offset", len(data))`, `\t\tr.set("length", len(it.${fn}))`, `\t\tdata = append(data, it.${fn}...)`);
          } else {
            L.push(`\t\tr.${f.t.optional ? "opt" : "set"}(${quote(f.name)}, it.${fn})`);
          }
        }
        L.push("\t\tlist[i] = r", "\t}", `\tparams.set(${quote(p.name)}, list)`);
      } else {
        L.push(`\tparams.${p.t.optional ? "opt" : "set"}(${quote(p.name)}, ${id})`);
      }
    }
    const bp = bytesParam(m);
    if (bp) data = ident("go", bp.name);
    if (r.base === "void") {
      L.push(`\treturn p.callAPI(${quote(m.method)}, ${params}, ${data}, nil)`);
    } else {
      L.push(`\t${decl}`);
      const target = isTyped(r) && !r.list && !r.optional ? "r" : "&r";
      L.push(`\terr := p.callAPI(${quote(m.method)}, ${params}, ${data}, ${target})`);
      L.push(`\t${tail}`);
    }
    L.push("}", "");
  }
  return goFile(L);
}

function goTypes() {
  const L = [];
  for (const t of Object.values(types)) {
    if (t.doc) L.push(...docLines("// ", `${typeName(t, "go")}: ${t.doc}`));
    L.push(`type ${typeName(t, "go")} struct {`);
    for (const f of t.fields) {
      if (f.doc) L.push(...docLines("\t// ", f.doc));
      const tag = t.record && f.t.base === "bytes" ? "-" : `${f.name}${f.t.optional ? ",omitempty" : ""}`;
      L.push(`\t${fieldName(f, "go")} ${f.goType ?? goType(f.t, { field: true })} \`json:"${tag}"\``);
    }
    L.push("}", "");
  }
  return goFile(L);
}

/* ======================================================================== */
/* Rust                                                                     */
/* ======================================================================== */

const rustScalar = { int: "i64", bool: "bool", string: "&str", json: "&str", bytes: "&[u8]" };
const recordHasRefs = (t) => t.fields.some((f) => ["string", "json", "bytes"].includes(f.t.base));
const rustRecordName = (t) => `${typeName(t, "rust")}${recordHasRefs(t) ? "<'a>" : ""}`;
const rustType = (t) => {
  if (t.list && types[t.base]?.record) {
    const rec = types[t.base];
    return `&[${typeName(rec, "rust")}${recordHasRefs(rec) ? "<'_>" : ""}]`;
  }
  const base = rustScalar[t.base];
  return t.optional ? `Option<${base}>` : base;
};
const rustResult = (r) =>
  r.base === "void" ? "()" : r.base === "bool" && !r.list ? "bool" : r.base === "int" && !r.list ? "i64" : "String";

function rustPush(L, indent, target, key, kind, value, optional) {
  if (optional) L.push(`${indent}if let Some(v) = ${value} {`, `${indent}    ${target}.${kind}(${quote(key)}, v);`, `${indent}}`);
  else L.push(`${indent}${target}.${kind}(${quote(key)}, ${value});`);
}

function rust() {
  const L = [
    `// ${HEADER}`,
    "",
    "//! Typed wrappers of the library methods and their records. Structured results are JSON text.",
    "",
    "use crate::{Error, ErrorKind, Printer, Result};",
    "",
  ];
  for (const t of records) {
    L.push(...docLines("/// ", t.doc ?? t.name));
    L.push("#[derive(Debug, Clone, Copy)]", `pub struct ${rustRecordName(t)} {`);
    for (const f of t.fields) {
      if (f.doc) L.push(...docLines("    /// ", f.doc));
      const base = { int: "i64", bool: "bool", string: "&'a str", json: "&'a str", bytes: "&'a [u8]" }[f.t.base];
      L.push(`    pub ${fieldName(f, "rust")}: ${f.t.optional ? `Option<${base}>` : base},`);
    }
    L.push("}", "");
  }
  L.push("impl Printer {");
  for (const m of forLang("rust")) {
    const args = m.params.map((p) => `, ${ident("rust", p.name)}: ${rustType(p.t)}`).join("");
    L.push(...docLines("    /// ", m.doc));
    L.push(`    pub fn ${methodName(m, "rust")}(&self${args}) -> Result<${rustResult(m.r)}> {`);
    let params = "None";
    let data = "None";
    if (jsonParams(m).length || m.consts.length) {
      L.push("        let mut p = Params::default();");
      params = "Some(&p.finish())";
    }
    for (const [k, v] of m.consts) L.push(`        p.${constKind(v)}(${quote(k)}, ${JSON.stringify(v)});`);
    for (const p of jsonParams(m)) {
      const id = ident("rust", p.name);
      if (isRecordParam(p)) {
        const rec = types[p.t.base];
        const bf = bytesOf(rec)[0];
        if (bf) {
          L.push("        let mut data = Vec::new();");
          data = "Some(&data)";
        }
        L.push('        let mut list = String::from("[");', `        for (i, it) in ${id}.iter().enumerate() {`);
        L.push("            if i > 0 {", "                list.push(',');", "            }", "            let mut r = Params::default();");
        for (const f of rec.fields) {
          const fn = fieldName(f, "rust");
          if (f === bf) {
            L.push(
              `            r.int("offset", data.len() as i64);`,
              `            r.int("length", it.${fn}.len() as i64);`,
              `            data.extend_from_slice(it.${fn});`,
            );
          } else {
            rustPush(L, "            ", "r", f.name, scalarKind(f.t.base), `it.${fn}`, f.t.optional);
          }
        }
        L.push("            list.push_str(&r.finish());", "        }", "        list.push(']');", `        p.raw(${quote(p.name)}, &list);`);
      } else {
        rustPush(L, "        ", "p", p.name, scalarKind(p.t.base), id, p.t.optional);
      }
    }
    const bp = bytesParam(m);
    if (bp) data = `Some(${ident("rust", bp.name)})`;
    const call = `self.call_binary(${quote(m.method)}, ${params}, ${data})`;
    const conv = {
      "()": `${call}.map(|_| ())`,
      bool: `${call}.and_then(|s| parse_bool(${quote(m.method)}, &s))`,
      i64: `${call}.and_then(|s| parse_int(${quote(m.method)}, &s))`,
      String: call,
    }[rustResult(m.r)];
    L.push(`        ${conv}`, "    }", "");
  }
  L[L.length - 1] = "}";
  L.push(
    "",
    "/// Builds a JSON params object.",
    "#[derive(Default)]",
    "struct Params(String);",
    "",
    "#[allow(dead_code)]",
    "impl Params {",
    "    fn key(&mut self, k: &str) {",
    "        self.0.push(if self.0.is_empty() { '{' } else { ',' });",
    "        push_json_str(&mut self.0, k);",
    "        self.0.push(':');",
    "    }",
    "    fn int(&mut self, k: &str, v: i64) {",
    "        self.key(k);",
    "        self.0.push_str(&v.to_string());",
    "    }",
    "    fn bool(&mut self, k: &str, v: bool) {",
    "        self.key(k);",
    '        self.0.push_str(if v { "true" } else { "false" });',
    "    }",
    "    fn string(&mut self, k: &str, v: &str) {",
    "        self.key(k);",
    "        push_json_str(&mut self.0, v);",
    "    }",
    "    fn raw(&mut self, k: &str, v: &str) {",
    "        self.key(k);",
    "        self.0.push_str(v);",
    "    }",
    "    fn finish(&self) -> String {",
    "        if self.0.is_empty() {",
    '            "{}".to_string()',
    "        } else {",
    '            format!("{}}}", self.0)',
    "        }",
    "    }",
    "}",
    "",
    "fn push_json_str(out: &mut String, s: &str) {",
    "    out.push('\"');",
    "    for c in s.chars() {",
    "        match c {",
    "            '\"' => out.push_str(\"\\\\\\\"\"),",
    "            '\\\\' => out.push_str(\"\\\\\\\\\"),",
    "            c if (c as u32) < 0x20 => out.push_str(&format!(\"\\\\u{:04x}\", c as u32)),",
    "            c => out.push(c),",
    "        }",
    "    }",
    "    out.push('\"');",
    "}",
    "",
    "#[allow(dead_code)]",
    "fn parse_int(method: &str, s: &str) -> Result<i64> {",
    "    s.trim().parse().map_err(|_| Error { kind: ErrorKind::Operation, message: format!(\"{method} returned {s}\") })",
    "}",
    "",
    "#[allow(dead_code)]",
    "fn parse_bool(method: &str, s: &str) -> Result<bool> {",
    "    match s.trim() {",
    '        "true" => Ok(true),',
    '        "false" => Ok(false),',
    "        _ => Err(Error { kind: ErrorKind::Operation, message: format!(\"{method} returned {s}\") }),",
    "    }",
    "}",
    "",
  );
  return L.join("\n");
}

/* ======================================================================== */
/* Python                                                                   */
/* ======================================================================== */

const pyType = (t) => (t.list ? "list" : { int: "int", bool: "bool", string: "str", json: "Any", bytes: "bytes" }[t.base]);
const pyResult = (r) => (r.list ? "list" : ({ void: "None", bool: "bool", int: "int", string: "Optional[str]" }[r.base] ?? "Any"));
const pyLiteral = (v) => (v === true ? "True" : v === false ? "False" : JSON.stringify(v));

function python() {
  const L = [
    `# ${HEADER}`,
    '"""Typed wrappers of the library methods (results are parsed JSON)."""',
    "",
    "import base64",
    "import json",
    "from typing import Any, Optional",
    "",
    "",
    "def _json_value(v: Any) -> Any:",
    '    """JSON text (str / bytes) is parsed, other values are sent as they are."""',
    "    if isinstance(v, bytes):",
    '        v = v.decode("utf-8")',
    "    return json.loads(v) if isinstance(v, str) else v",
    "",
    "",
    "def _decode_bytes(v: Any, keys: tuple) -> Any:",
    '    """Base64 fields of a result (object or list of objects) become bytes."""',
    "    for item in v if isinstance(v, list) else [v]:",
    "        if isinstance(item, dict):",
    "            for k in keys:",
    "                if isinstance(item.get(k), str):",
    "                    item[k] = base64.b64decode(item[k])",
    "    return v",
    "",
    "",
    "class _PrinterAPI:",
    '    """Library methods, implemented on top of Printer._call_binary."""',
    "",
    "    def _call_binary(self, method: str, params: Optional[dict], data: Optional[bytes]) -> Any:",
    "        raise NotImplementedError",
  ];
  const val = (p, v) => (p.t.base === "json" ? `_json_value(${v})` : v);
  for (const m of forLang("python")) {
    const args = m.params
      .map((p) => `, ${ident("python", p.name)}: ${p.t.optional ? `Optional[${pyType(p.t)}] = None` : pyType(p.t)}`)
      .join("");
    L.push("", `    def ${methodName(m, "python")}(self${args}) -> ${pyResult(m.r)}:`);
    let doc = m.doc;
    for (const p of m.params.filter(isRecordParam)) {
      const rec = types[p.t.base];
      const keys = rec.fields.map((f) => `"${f.name}"${f.t.optional ? "?" : ""}`).join(", ");
      doc += ` ${ident("python", p.name)}: list of dicts {${keys}}.`;
    }
    const d = wrap(doc, 88);
    L.push(...(d.length === 1 ? [`        """${d[0]}"""`] : [`        """${d[0]}`, ...d.slice(1).map((l) => `        ${l}`), '        """']));
    const jp = jsonParams(m);
    let params = "None";
    let data = "None";
    if (jp.length || m.consts.length) {
      const entries = [
        ...m.consts.map(([k, v]) => `${quote(k)}: ${pyLiteral(v)}`),
        ...jp.filter((p) => !p.t.optional && !isRecordParam(p)).map((p) => `${quote(p.name)}: ${val(p, ident("python", p.name))}`),
      ];
      L.push(`        params: dict = {${entries.join(", ")}}`);
      params = "params";
    }
    for (const p of jp) {
      const id = ident("python", p.name);
      if (isRecordParam(p)) {
        const rec = types[p.t.base];
        const bf = bytesOf(rec)[0];
        if (bf) {
          L.push("        chunks: list = []", "        size = 0");
          data = 'b"".join(chunks)';
        }
        L.push("        items: list = []", `        for it in ${id}:`);
        const req = rec.fields.filter((f) => !f.t.optional && f !== bf);
        L.push(`            r: dict = {${req.map((f) => `${quote(f.name)}: ${val(f, `it[${quote(f.name)}]`)}`).join(", ")}}`);
        for (const f of rec.fields) {
          if (f === bf) {
            L.push(
              `            b = bytes(it[${quote(f.name)}])`,
              '            r["offset"], r["length"] = size, len(b)',
              "            chunks.append(b)",
              "            size += len(b)",
            );
          } else if (f.t.optional) {
            L.push(`            if it.get(${quote(f.name)}) is not None:`, `                r[${quote(f.name)}] = ${val(f, `it[${quote(f.name)}]`)}`);
          }
        }
        L.push("            items.append(r)", `        params[${quote(p.name)}] = items`);
      } else if (p.t.optional) {
        L.push(`        if ${id} is not None:`, `            params[${quote(p.name)}] = ${val(p, id)}`);
      }
    }
    const bp = bytesParam(m);
    if (bp) data = `bytes(${ident("python", bp.name)})`;
    const call = `self._call_binary(${quote(m.method)}, ${params}, ${data})`;
    const bytesFields = (types[m.r.base]?.fields ?? []).filter((f) => f.t.base === "bytes").map((f) => quote(f.name));
    if (m.r.base === "void") L.push(`        ${call}`);
    else if (bytesFields.length) L.push(`        return _decode_bytes(${call}, (${bytesFields.join(", ")},))`);
    else L.push(`        return ${call}`);
  }
  L.push("");
  return L.join("\n");
}

/* ======================================================================== */
/* Swift                                                                    */
/* ======================================================================== */

const swiftScalar = { int: "Int", bool: "Bool", string: "String", json: "String", bytes: "Data" };
const swiftType = (t) =>
  t.list && types[t.base]?.record ? `[${typeName(types[t.base], "swift")}]` : swiftScalar[t.base] + (t.optional ? "? = nil" : "");
const swiftResult = (r) =>
  r.base === "void" ? null : !r.list && r.base === "bool" ? "Bool" : !r.list && r.base === "int" ? "Int" : "String";

function swiftPush(L, indent, target, key, kind, value, optional) {
  if (optional) L.push(`${indent}if let v = ${value} { ${target}.${kind}(${quote(key)}, v) }`);
  else L.push(`${indent}${target}.${kind}(${quote(key)}, ${value})`);
}

function swift() {
  const L = [`// ${HEADER}`, "", "import Foundation", ""];
  for (const t of records) {
    const n = typeName(t, "swift");
    L.push(...docLines("/// ", t.doc ?? n), `public struct ${n}: Sendable {`);
    for (const f of t.fields) {
      if (f.doc) L.push(...docLines("    /// ", f.doc));
      L.push(`    public var ${fieldName(f, "swift")}: ${swiftScalar[f.t.base]}${f.t.optional ? "?" : ""}`);
    }
    L.push("");
    L.push(
      `    public init(${t.fields.map((f) => `${fieldName(f, "swift")}: ${swiftScalar[f.t.base]}${f.t.optional ? "? = nil" : ""}`).join(", ")}) {`,
    );
    for (const f of t.fields) L.push(`        self.${fieldName(f, "swift")} = ${fieldName(f, "swift")}`);
    L.push("    }", "}", "");
  }
  L.push("/// Typed wrappers of the library methods. Structured results are JSON text.", "extension NiimPrinter {");
  for (const m of forLang("swift")) {
    // The first param is unlabeled when it is the only required one
    const unlabeled = m.params.length > 0 && !m.params[0].t.optional && m.params.slice(1).every((p) => p.t.optional);
    const args = m.params.map((p, i) => `${unlabeled && i === 0 ? "_ " : ""}${p.name}: ${swiftType(p.t)}`).join(", ");
    const res = swiftResult(m.r);
    L.push(...docLines("    /// ", m.doc));
    if (res) L.push("    @discardableResult");
    L.push(`    public func ${methodName(m, "swift")}(${args}) throws${res ? ` -> ${res}` : ""} {`);
    let params = "nil";
    let data = "nil";
    if (jsonParams(m).length || m.consts.length) {
      L.push("        var p = APIParams()");
      params = "p.json";
    }
    for (const [k, v] of m.consts) L.push(`        p.${constKind(v)}(${quote(k)}, ${JSON.stringify(v)})`);
    for (const p of jsonParams(m)) {
      if (isRecordParam(p)) {
        const rec = types[p.t.base];
        const bf = bytesOf(rec)[0];
        if (bf) {
          L.push("        var data = Data()");
          data = "data";
        }
        L.push("        var items: [String] = []", `        for it in ${p.name} {`, "            var r = APIParams()");
        for (const f of rec.fields) {
          const fn = fieldName(f, "swift");
          if (f === bf) {
            L.push(`            r.int("offset", data.count)`, `            r.int("length", it.${fn}.count)`, `            data.append(it.${fn})`);
          } else {
            swiftPush(L, "            ", "r", f.name, scalarKind(f.t.base), `it.${fn}`, f.t.optional);
          }
        }
        L.push("            items.append(r.json)", "        }", `        p.raw(${quote(p.name)}, "[" + items.joined(separator: ",") + "]")`);
      } else {
        swiftPush(L, "        ", "p", p.name, scalarKind(p.t.base), p.name, p.t.optional);
      }
    }
    const bp = bytesParam(m);
    if (bp) data = bp.name;
    const call = `try callBinary(${quote(m.method)}, params: ${params}, data: ${data})`;
    if (!res) L.push(`        _ = ${call}`);
    else if (res === "Bool") L.push(`        return try parseBool(${quote(m.method)}, ${call})`);
    else if (res === "Int") L.push(`        return try parseInt(${quote(m.method)}, ${call})`);
    else L.push(`        return ${call}`);
    L.push("    }", "");
  }
  L[L.length - 1] = "}";
  L.push(
    "",
    "/// Builds a JSON params object.",
    "struct APIParams {",
    '    private var body = ""',
    "",
    "    private mutating func key(_ k: String) {",
    '        body += body.isEmpty ? "{" : ","',
    '        body += apiJSONString(k) + ":"',
    "    }",
    "    mutating func int(_ k: String, _ v: Int) { key(k); body += String(v) }",
    '    mutating func bool(_ k: String, _ v: Bool) { key(k); body += v ? "true" : "false" }',
    "    mutating func string(_ k: String, _ v: String) { key(k); body += apiJSONString(v) }",
    "    mutating func raw(_ k: String, _ v: String) { key(k); body += v }",
    '    var json: String { body.isEmpty ? "{}" : body + "}" }',
    "}",
    "",
    "func apiJSONString(_ s: String) -> String {",
    '    var out = "\\""',
    "    for u in s.unicodeScalars {",
    "        switch u {",
    '        case "\\"": out += "\\\\\\""',
    '        case "\\\\": out += "\\\\\\\\"',
    '        case _ where u.value < 0x20: out += String(format: "\\\\u%04x", u.value)',
    "        default: out.unicodeScalars.append(u)",
    "        }",
    "    }",
    '    return out + "\\""',
    "}",
    "",
    "private func parseInt(_ method: String, _ s: String) throws -> Int {",
    "    guard let v = Int(s.trimmingCharacters(in: .whitespacesAndNewlines)) else {",
    '        throw NiimError(code: NiimError.operation, message: "\\(method) returned \\(s)")',
    "    }",
    "    return v",
    "}",
    "",
    "private func parseBool(_ method: String, _ s: String) throws -> Bool {",
    "    switch s.trimmingCharacters(in: .whitespacesAndNewlines) {",
    '    case "true": return true',
    '    case "false": return false',
    '    default: throw NiimError(code: NiimError.operation, message: "\\(method) returned \\(s)")',
    "    }",
    "}",
    "",
  );
  return L.join("\n");
}

/* ======================================================================== */
/* Kotlin                                                                   */
/* ======================================================================== */

const ktScalar = { int: "Int", bool: "Boolean", string: "String", json: "String", bytes: "ByteArray" };
const ktType = (t) =>
  t.list && types[t.base]?.record ? `List<${typeName(types[t.base], "kotlin")}>` : ktScalar[t.base] + (t.optional ? "? = null" : "");
const ktResult = (r) =>
  r.base === "void" ? "Unit" : !r.list && r.base === "bool" ? "Boolean" : !r.list && r.base === "int" ? "Int" : "String";

function ktPush(L, indent, target, key, kind, value, optional) {
  if (optional) L.push(`${indent}${value}?.let { ${target}.${kind}(${quote(key)}, it) }`);
  else L.push(`${indent}${target}.${kind}(${quote(key)}, ${value})`);
}

const ktDoc = (indent, text) => {
  const d = wrap(text, 92);
  return d.length === 1 ? [`${indent}/** ${d[0]} */`] : [`${indent}/**`, ...d.map((l) => `${indent} * ${l}`), `${indent} */`];
};

function kotlin() {
  const L = [`// ${HEADER}`, "", "package io.github.multimote.niimblue", ""];
  for (const t of records) {
    const n = typeName(t, "kotlin");
    L.push(...ktDoc("", t.doc ?? n));
    L.push(`class ${n} @JvmOverloads constructor(`);
    for (const f of t.fields) L.push(`    val ${fieldName(f, "kotlin")}: ${ktScalar[f.t.base]}${f.t.optional ? "? = null" : ""},`);
    L.push(")", "");
  }
  L.push(
    "/**",
    " * Typed wrappers of the library methods, implemented by [NiimPrinter] on top of",
    " * niim_call_bin. Structured results are JSON text.",
    " */",
    "abstract class NiimPrinterApi internal constructor() {",
    "    /** [method] with a JSON params object (or null) and a binary payload (or null); returns the JSON result. */",
    "    internal abstract fun apiCall(method: String, paramsJson: String?, data: ByteArray?): String",
  );
  for (const m of forLang("kotlin")) {
    const args = m.params.map((p) => `${ident("kotlin", p.name)}: ${ktType(p.t)}`).join(", ");
    const res = ktResult(m.r);
    L.push("", ...ktDoc("    ", m.doc));
    if (m.params.some((p) => p.t.optional)) L.push("    @JvmOverloads");
    L.push(`    fun ${methodName(m, "kotlin")}(${args})${res === "Unit" ? "" : `: ${res}`} {`);
    let params = "null";
    let data = "null";
    if (jsonParams(m).length || m.consts.length) {
      L.push("        val p = ApiParams()");
      params = "p.json()";
    }
    for (const [k, v] of m.consts) L.push(`        p.${constKind(v)}(${quote(k)}, ${JSON.stringify(v)})`);
    for (const p of jsonParams(m)) {
      const id = ident("kotlin", p.name);
      if (isRecordParam(p)) {
        const rec = types[p.t.base];
        const bf = bytesOf(rec)[0];
        if (bf) {
          L.push("        val buf = java.io.ByteArrayOutputStream()");
          data = "buf.toByteArray()";
        }
        L.push(`        val items = ${id}.map { item ->`, "            val r = ApiParams()");
        for (const f of rec.fields) {
          const fn = fieldName(f, "kotlin");
          if (f === bf) {
            L.push(`            r.int("offset", buf.size())`, `            r.int("length", item.${fn}.size)`, `            buf.write(item.${fn})`);
          } else {
            ktPush(L, "            ", "r", f.name, scalarKind(f.t.base), `item.${fn}`, f.t.optional);
          }
        }
        L.push("            r.json()", "        }", `        p.raw(${quote(p.name)}, items.joinToString(",", "[", "]"))`);
      } else {
        ktPush(L, "        ", "p", p.name, scalarKind(p.t.base), id, p.t.optional);
      }
    }
    const bp = bytesParam(m);
    if (bp) data = ident("kotlin", bp.name);
    const call = `apiCall(${quote(m.method)}, ${params}, ${data})`;
    if (res === "Unit") L.push(`        ${call}`);
    else if (res === "Boolean") L.push(`        return parseApiBool(${quote(m.method)}, ${call})`);
    else if (res === "Int") L.push(`        return parseApiInt(${quote(m.method)}, ${call})`);
    else L.push(`        return ${call}`);
    L.push("    }");
  }
  L.push(
    "}",
    "",
    "/** Builds a JSON params object. */",
    "internal class ApiParams {",
    "    private val sb = StringBuilder()",
    "",
    "    private fun key(k: String) {",
    "        sb.append(if (sb.isEmpty()) '{' else ',')",
    "        appendJsonString(sb, k)",
    "        sb.append(':')",
    "    }",
    "",
    "    fun int(k: String, v: Int) { key(k); sb.append(v) }",
    "    fun bool(k: String, v: Boolean) { key(k); sb.append(v) }",
    "    fun string(k: String, v: String) { key(k); appendJsonString(sb, v) }",
    "    fun raw(k: String, v: String) { key(k); sb.append(v) }",
    '    fun json(): String = if (sb.isEmpty()) "{}" else "$sb}"',
    "}",
    "",
    "internal fun appendJsonString(sb: StringBuilder, s: String) {",
    "    sb.append('\"')",
    "    for (c in s) {",
    "        when {",
    "            c == '\"' -> sb.append(\"\\\\\\\"\")",
    "            c == '\\\\' -> sb.append(\"\\\\\\\\\")",
    "            c < ' ' -> sb.append(\"\\\\u%04x\".format(c.code))",
    "            else -> sb.append(c)",
    "        }",
    "    }",
    "    sb.append('\"')",
    "}",
    "",
    "private fun parseApiInt(method: String, s: String): Int =",
    '    s.trim().toIntOrNull() ?: throw NiimException(NiimException.OPERATION, "$method returned $s")',
    "",
    "private fun parseApiBool(method: String, s: String): Boolean = when (s.trim()) {",
    '    "true" -> true',
    '    "false" -> false',
    '    else -> throw NiimException(NiimException.OPERATION, "$method returned $s")',
    "}",
    "",
  );
  return L.join("\n");
}

/* ======================================================================== */
/* C header: method list (from api.json) and FFI declarations (from it)     */
/* ======================================================================== */

function headerMethods(current) {
  const begin = " * BEGIN GENERATED METHODS\n";
  const end = " * END GENERATED METHODS\n";
  const a = current.indexOf(begin);
  const b = current.indexOf(end);
  if (a < 0 || b < a) fail("include/niimblue.h: generated method markers missing");
  const lines = [];
  for (const m of methods) {
    const keys = [
      ...m.consts.map(([k, v]) => `"${k}":${JSON.stringify(v)}`),
      ...jsonParams(m).map((p) => {
        if (!isRecordParam(p)) return `"${p.name}"${p.t.optional ? "?" : ""}`;
        const rec = types[p.t.base];
        const fs = rec.fields.map((f) => (f.t.base === "bytes" ? '"offset","length"' : `"${f.name}"${f.t.optional ? "?" : ""}`));
        return `"${p.name}":[{${fs.join(",")}}]`;
      }),
    ];
    const ps = keys.length ? ` {${keys.join(",")}}` : "";
    const bin = hasBinary(m) ? " + data" : "";
    const res = m.r.base === "void" ? "" : ` -> ${m.result}`;
    lines.push(` *   ${m.method}${ps}${bin}${res}`);
    lines.push(...docLines(" *       ", `${m.name}: ${m.doc}`, 100));
  }
  return current.slice(0, a + begin.length) + lines.join("\n") + "\n" + current.slice(b);
}

/** Functions, callback typedefs, structs and NIIM_* constants of the header. */
function parseHeader(src) {
  const code = src.replace(/\/\*[\s\S]*?\*\//g, " ").replace(/\/\/.*$/gm, " ");
  const norm = (t) => t.replace(/\s+/g, " ").replace(/\s*\*\s*/g, "*").trim();
  const splitDecl = (d) => {
    const m = d.trim().match(/^(.*?[\s*])(\w+)$/s);
    if (!m) fail(`include/niimblue.h: can't parse declaration "${d.trim()}"`);
    return { type: norm(m[1]), name: m[2] };
  };
  const args = (s) => (s.trim() === "void" || s.trim() === "" ? [] : s.split(",").map(splitDecl));

  const consts = [...code.matchAll(/#define\s+(NIIM_(?:OK|E_\w+))\s+(-?\d+)/g)].map((m) => ({ name: m[1], value: +m[2] }));
  const opaque = [...code.matchAll(/typedef\s+struct\s+(\w+)\s+(\w+)\s*;/g)].map((m) => m[2]);
  const callbacks = [...code.matchAll(/typedef\s+([\w\s*]+?)\s*\(\s*\*\s*(\w+)\s*\)\s*\(([^)]*)\)\s*;/g)].map((m) => ({
    name: m[2],
    ret: norm(m[1]),
    args: args(m[3]),
  }));
  const structs = [...code.matchAll(/typedef\s+struct\s*\{([^}]*)\}\s*(\w+)\s*;/g)].map((m) => ({
    name: m[2],
    fields: m[1]
      .split(";")
      .filter((s) => s.trim())
      .flatMap((decl) => {
        const [first, ...more] = decl.split(",");
        const f = splitDecl(first);
        return [f, ...more.map((n) => ({ type: f.type, name: n.trim() }))];
      }),
  }));
  const functions = [...code.matchAll(/NIIM_API\s+([^;(]*?)\s*\b(\w+)\s*\(([^)]*)\)\s*;/g)].map((m) => ({
    ret: norm(m[1]),
    name: m[2],
    args: args(m[3]),
  }));
  if (!functions.length) fail("include/niimblue.h: no NIIM_API functions found");
  return { consts, opaque, callbacks, structs, functions };
}

function rustSys(h) {
  const named = new Set([...h.opaque, ...h.callbacks.map((c) => c.name), ...h.structs.map((s) => s.name)]);
  const BASE = { void: "c_void", int: "c_int", char: "c_char", size_t: "usize", uint32_t: "u32", uint8_t: "u8", int32_t: "i32", int64_t: "i64" };
  const ty = (t) => {
    const stars = (t.match(/\*/g) ?? []).length;
    const isConst = /^const /.test(t);
    const base = t.replace(/^const /, "").replace(/\*/g, "").trim();
    let r = named.has(base) ? base : BASE[base];
    if (!r) fail(`include/niimblue.h: no Rust type for ${t}`);
    for (let i = 0; i < stars; i++) r = `${i === 0 && isConst ? "*const" : "*mut"} ${r}`;
    return r;
  };
  const ret = (t) => (t === "void" ? "" : ` -> ${ty(t)}`);
  const L = [
    `// ${FFI_HEADER}`,
    "",
    "//! Raw C API (see include/niimblue.h).",
    "",
    "#![allow(non_camel_case_types)]",
    "",
    "use std::ffi::{c_char, c_int, c_void};",
    "",
  ];
  for (const o of h.opaque) L.push("#[repr(C)]", `pub struct ${o} {`, "    _private: [u8; 0],", "}", "");
  for (const c of h.callbacks) {
    L.push(`pub type ${c.name} = Option<unsafe extern "C" fn(${c.args.map((a) => `${a.name}: ${ty(a.type)}`).join(", ")})${ret(c.ret)}>;`);
  }
  L.push("");
  for (const s of h.structs) {
    L.push("#[repr(C)]", `pub struct ${s.name} {`);
    for (const f of s.fields) L.push(`    pub ${f.name}: ${ty(f.type)},`);
    L.push("}", "");
  }
  for (const c of h.consts) L.push(`pub const ${c.name}: c_int = ${c.value};`);
  L.push("", 'extern "C" {');
  for (const f of h.functions) L.push(`    pub fn ${f.name}(${f.args.map((a) => `${a.name}: ${ty(a.type)}`).join(", ")})${ret(f.ret)};`);
  L.push("}", "");
  return L.join("\n");
}

function pythonFFI(h) {
  const named = new Set([...h.opaque]);
  const cbs = new Set(h.callbacks.map((c) => c.name));
  const structs = new Set(h.structs.map((s) => s.name));
  const BASE = {
    int: "ctypes.c_int",
    size_t: "ctypes.c_size_t",
    uint32_t: "ctypes.c_uint32",
    uint8_t: "ctypes.c_uint8",
    int32_t: "ctypes.c_int32",
    int64_t: "ctypes.c_int64",
  };
  // ctx: "arg" | "ret" | "cb" (callback argument) | "field"
  const ty = (t, ctx) => {
    const stars = (t.match(/\*/g) ?? []).length;
    const base = t.replace(/^const /, "").replace(/\*/g, "").trim();
    if (stars === 0) {
      if (t === "void") return "None";
      if (cbs.has(base)) return base.toUpperCase();
      if (BASE[base]) return BASE[base];
    } else if (stars === 2 && base === "char") {
      return "OUT";
    } else if (stars === 1) {
      // Non-const strings are owned by the library (returned, then given back to niim_string_free): keep the pointer
      if (base === "char") return /^const /.test(t) ? "ctypes.c_char_p" : "ctypes.c_void_p";
      if (base === "uint8_t") return ctx === "cb" ? "ctypes.POINTER(ctypes.c_uint8)" : ctx === "field" ? "ctypes.c_void_p" : "ctypes.c_char_p";
      if (structs.has(base)) return `ctypes.POINTER(${base})`;
      if (base === "void" || named.has(base)) return "ctypes.c_void_p";
    }
    fail(`include/niimblue.h: no ctypes type for ${t}`);
  };
  const L = [
    `# ${FFI_HEADER}`,
    '"""ctypes declarations of the C API (include/niimblue.h)."""',
    "",
    "import ctypes",
    "from types import SimpleNamespace",
    "",
    "OUT = ctypes.POINTER(ctypes.c_void_p)",
  ];
  for (const c of h.consts) L.push(`${c.name} = ${c.value}`);
  for (const c of h.callbacks) {
    L.push(`${c.name.toUpperCase()} = ctypes.CFUNCTYPE(${[ty(c.ret, "ret"), ...c.args.map((a) => ty(a.type, "cb"))].join(", ")})`);
  }
  for (const s of h.structs) {
    L.push("", "", `class ${s.name}(ctypes.Structure):`, "    _fields_ = [");
    for (const f of s.fields) L.push(`        (${quote(f.name)}, ${ty(f.type, "field")}),`);
    L.push("    ]");
  }
  L.push(
    "",
    "",
    "def bind(lib: ctypes.CDLL) -> SimpleNamespace:",
    '    """The C functions of `lib` with their signatures, named without the niim_ prefix."""',
    "",
    "    def fn(name, restype, *argtypes):",
    "        f = getattr(lib, name)",
    "        f.restype = restype",
    "        f.argtypes = list(argtypes)",
    "        return f",
    "",
    "    return SimpleNamespace(",
  );
  for (const f of h.functions) {
    const parts = [quote(f.name), ty(f.ret, "ret"), ...f.args.map((a) => ty(a.type, "arg"))];
    L.push(`        ${f.name.replace(/^niim_/, "")}=fn(${parts.join(", ")}),`);
  }
  L.push("    )", "");
  return L.join("\n");
}

/* ======================================================================== */
/* Write / check                                                            */
/* ======================================================================== */

const headerSrc = headerMethods(read("include/niimblue.h"));
const ffi = parseHeader(headerSrc);
const KT = "bindings/kotlin/niimblue/src/jniMain/kotlin/io/github/multimote/niimblue";
const outputs = [
  ["include/niimblue.h", headerSrc],
  ["go/zz_api.go", goMethods()],
  ["go/zz_api_types.go", goTypes()],
  ["bindings/rust/src/api.rs", rust()],
  ["bindings/rust/src/sys.rs", rustSys(ffi)],
  ["bindings/python/niimblue/_api.py", python()],
  ["bindings/python/niimblue/_ffi.py", pythonFFI(ffi)],
  ["bindings/swift/Sources/Niimblue/NiimPrinter+API.swift", swift()],
  [`${KT}/NiimPrinterApi.kt`, kotlin()],
];

let stale = 0;
for (const [rel, content] of outputs) {
  const path = join(ROOT, rel);
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === content) continue;
  if (CHECK) {
    console.error(`api: ${rel} is out of date, run \`npm run gen\``);
    stale++;
  } else {
    writeFileSync(path, content);
    console.log(`api: wrote ${rel}`);
  }
}
if (stale) process.exit(1);
if (CHECK) console.log(`api: ${methods.length} methods, ${ffi.functions.length} C functions, generated files up to date`);
